contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _asset) public {
        // Fresh adapter: utilizationData[_vault][_asset].lastUpdate == 0.
        // First call: index is read from the vault, elapsed == block.timestamp,
        // so utilization is taken from the vault; state is updated to now.
        uint256 r1 = c.rate(address(this), _asset); if (__ESBMC_reverted()) return;
        // Second call in the same transaction: block.timestamp == lastUpdate,
        // so utilization is again taken from the vault (same value), and the
        // multiplier changes only proportionally to elapsed == 0.
        uint256 r2 = c.rate(address(this), _asset); if (__ESBMC_reverted()) return;
        assert(r1 == r2);
    }

    fallback(bytes calldata) external returns (bytes memory) {
        // Emulate a minimal vault: currentUtilizationIndex -> 0, utilization -> 1e27
        if (msg.sig == bytes4(keccak256("currentUtilizationIndex(address)"))) {
            return abi.encode(uint256(0));
        }
        if (msg.sig == bytes4(keccak256("utilization(address)"))) {
            return abi.encode(uint256(1e27));
        }
        return "";
    }

    receive() external payable {}
}

