pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    VaultAdapter c;

    function setUp() public {
        c = new VaultAdapter();
    }

    function _run(address _asset) internal {
        uint256 r1;
        try c.rate(address(this), _asset) returns (uint256 __r) { r1 = __r; } catch { return; }
        uint256 r2;
        try c.rate(address(this), _asset) returns (uint256 __r) { r2 = __r; } catch { return; }
        assertTrue(r1 == r2);
    }

    function testFuzz_run(address _asset) public {
        vm.assume(_asset.code.length == 0 && uint160(_asset) > 0xffff && _asset != address(this) && _asset != address(c) && _asset != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _asset != 0x000000000000000000636F6e736F6c652e6c6f67 && _asset != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _asset != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_asset);
    }

    fallback(bytes calldata) external returns (bytes memory) {
        // Emulate a minimal vault: currentUtilizationIndex -> 0, utilization -> 1e27
        if (msg.sig == bytes4(keccak256("currentUtilizationIndex(address)"))) {
            return abi.encode(uint256(0));
        }
        if (msg.sig == bytes4(keccak256("utilization(address)"))) {
            return abi.encode(uint256(1e27));
        }
        return "";
    }

    receive() external payable {}
}
